(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"experiment":{"h":"WHAT YOU ARE LOOKING AT","t":"We roll a **fair six-sided die**. Before the roll, nobody can say which face will come up. An experiment whose result is uncertain is called a **random experiment**."},"possible-outcomes":{"h":"THE POSSIBLE OUTCOMES","t":"Each possible result is an **outcome**. A die has six: **1, 2, 3, 4, 5 and 6**. Exactly one of them happens on every roll."},"sample-space":{"h":"THE SAMPLE SPACE","t":"The set of all possible outcomes is the **sample space**: **{1, 2, 3, 4, 5, 6}**. Everything we will ask about lives inside it."},"event":{"h":"AN EVENT IS A GROUP OF OUTCOMES","t":"An **event** is any collection of outcomes we care about. “The roll is even” is the event **{2, 4, 6}**. It happens whenever the roll lands on one of those faces."},"assign-probability":{"h":"GIVE EACH OUTCOME A PROBABILITY","t":"A fair die gives each face probability **1/6**. The probability of an event is the **sum over its outcomes**: P(even) = 1/6 + 1/6 + 1/6 = **1/2**."},"valid-probabilities":{"h":"WHAT MAKES PROBABILITIES VALID","t":"Every probability must be **between 0 and 1**, and all outcomes together must **add to exactly 1**. Six faces at 1/6 add to 1. Six faces at 0.2 would add to 1.2, which is not valid."},"ml-connection":{"h":"TAKEAWAY","t":"A classifier that outputs **spam 0.9 and not spam 0.1** is assigning probabilities to its two possible outcomes. They must **add to 1**, or the output is not a coherent belief."}};
  // ── scene ──
  var steps = [
    { id: "experiment", label: "A random experiment", caption: "Roll a fair six-sided die. Before the roll, nobody can say which face will come up. An experiment whose result is uncertain is called a random experiment." },
    { id: "possible-outcomes", label: "The possible outcomes", caption: "Each possible result is an outcome. A die has six: 1, 2, 3, 4, 5 and 6. Exactly one of them happens on every roll." },
    { id: "sample-space", label: "The sample space", caption: "The set of all possible outcomes is the sample space: {1, 2, 3, 4, 5, 6}. Everything we will ask about lives inside it." },
    { id: "event", label: "An event is a group of outcomes", caption: "An event is any collection of outcomes we care about. 'The roll is even' is the event {2, 4, 6}. It happens whenever the roll lands on one of those faces." },
    { id: "assign-probability", label: "Give each outcome a probability", caption: "A fair die gives each face probability 1/6. The probability of an event is the sum over its outcomes: P(even) = 1/6 + 1/6 + 1/6 = 1/2." },
    { id: "valid-probabilities", label: "What makes probabilities valid", caption: "Every probability must be between 0 and 1, and all outcomes together must add to exactly 1. Six faces at 1/6 add to 1. Six faces at 0.2 would add to 1.2, which is not valid." },
    { id: "ml-connection", label: "The same rule inside a model", caption: "A classifier that outputs spam 0.9 and not spam 0.1 is assigning probabilities to its two possible outcomes. They must add to 1, or the output is not a coherent belief." }
  ];

  var FX = function (i) { return 40 + i * 96; };
  var faces = [], nums = [], bars = [], barLbls = [];
  var big = el("g", {}, svg);
  card(big, 245, 100, 150, 130, "fillA");
  txt(big, 320, 180, "big", "?", "middle").setAttribute("font-size", "48");
  txt(big, 320, 262, "note", "roll the die: which face?", "middle");

  var facesG = el("g", {}, svg);
  for (var i = 0; i < 6; i++) {
    faces.push(box(facesG, FX(i), 120, 80, 80, "rgba(56,189,248,0.16)", "#38bdf8", 12));
    nums.push(txt(facesG, FX(i) + 40, 172, "big", String(i + 1), "middle"));
    nums[i].setAttribute("font-size", "30");
  }
  var spaceBox = el("rect", { x: 28, y: 108, width: 584, height: 104, rx: 14, fill: "none", stroke: "#e2b44a", "stroke-width": 2.5, "stroke-dasharray": "7 5" }, svg);
  var spaceLbl = txt(svg, 320, 96, "lbl lbl-y", "sample space = {1, 2, 3, 4, 5, 6}", "middle");
  var evLbl = txt(svg, 320, 232, "lbl lbl-p", "event: the roll is even = {2, 4, 6}", "middle");
  var outLbl = txt(svg, 320, 96, "lbl", "six possible outcomes", "middle");

  var barsG = el("g", {}, svg);
  for (var j = 0; j < 6; j++) {
    bars.push(box(barsG, FX(j) + 20, 336 - 48, 40, 48, "rgba(56,189,248,0.5)", "#38bdf8", 4));
    barLbls.push(txt(barsG, FX(j) + 40, 336 - 54, "lbl", "1/6", "middle"));
  }
  el("line", { x1: 30, y1: 336, x2: 610, y2: 336, class: "axis" }, barsG);
  var sumLbl = txt(svg, 320, 258, "big", "P(even) = 1/6 + 1/6 + 1/6 = 1/2", "middle");

  // Validity bars.
  var validG = el("g", {}, svg);
  var W = 420, X0 = 90;
  txt(validG, X0, 122, "lbl lbl-g", "valid: six faces at 1/6", "start");
  for (var k = 0; k < 6; k++) box(validG, X0 + (W / 6) * k, 132, W / 6 - 2, 36, k % 2 ? "rgba(29,181,132,0.55)" : "rgba(29,181,132,0.8)", "none", 4);
  txt(validG, X0 + W + 14, 156, "big", "= 1", "start");
  el("line", { x1: X0 + W, y1: 124, x2: X0 + W, y2: 300, stroke: "#c9dccf", "stroke-width": 2, "stroke-dasharray": "5 4" }, validG);
  txt(validG, X0 + W, 316, "note", "total of 1", "middle");
  txt(validG, X0, 222, "lbl lbl-r", "not valid: six faces at 0.2", "start");
  for (var m = 0; m < 6; m++) box(validG, X0 + (W / 5) * m, 232, W / 5 - 2, 36, m % 2 ? "rgba(248,113,113,0.55)" : "rgba(248,113,113,0.8)", "none", 4);
  txt(validG, X0, 296, "big", "adds up to 1.2: too much", "start").setAttribute("fill", "#f87171");

  var mlG = el("g", {}, svg);
  card(mlG, 40, 110, 150, 80, "fillB");
  txt(mlG, 115, 142, "note", "classifier output", "middle");
  txt(mlG, 115, 170, "lbl", "for one email", "middle");
  var a1 = arrow(mlG, "w", 3); setLine(a1, 194, 150, 250, 150);
  box(mlG, 260, 130, 0.9 * 330, 40, "rgba(244,114,182,0.8)", "none", 4);
  box(mlG, 260 + 0.9 * 330, 130, 0.1 * 330, 40, "rgba(56,189,248,0.8)", "none", 4);
  txt(mlG, 260 + 0.45 * 330, 156, "lbl", "spam 0.9", "middle");
  txt(mlG, 260 + 0.95 * 330, 198, "lbl lbl-b", "not spam 0.1", "middle");
  txt(mlG, 425, 244, "big", "0.9 + 0.1 = 1", "middle");
  txt(mlG, 425, 276, "note", "a valid probability assignment over two outcomes", "middle");

  function render(index, id) {
    var i = index;
    show(big, i === 0);
    show(facesG, i >= 1 && i <= 4);
    show(outLbl, i === 1);
    show(spaceBox, i >= 2 && i <= 4);
    show(spaceLbl, i >= 2 && i <= 4);
    show(evLbl, i === 3 || i === 4);
    show(barsG, i === 4);
    show(sumLbl, i === 4);
    show(validG, i === 5);
    show(mlG, i === 6);
    evLbl.setAttribute("y", 232);
    for (var f = 0; f < 6; f++) {
      var isEven = (f + 1) % 2 === 0;
      var hi = (i >= 3) && isEven;
      faces[f].setAttribute("fill", hi ? "rgba(244,114,182,0.4)" : "rgba(56,189,248,0.16)");
      faces[f].setAttribute("stroke", hi ? "#f472b6" : "#38bdf8");
      bars[f].setAttribute("fill", isEven ? "rgba(244,114,182,0.7)" : "rgba(56,189,248,0.35)");
      bars[f].setAttribute("stroke", isEven ? "#f472b6" : "#38bdf8");
      faces[f].setAttribute("opacity", "1");
      nums[f].setAttribute("opacity", "1");
    }
      if (i === 1) {
      anim("faces", 1100, function (e) {
        for (var q = 0; q < 6; q++) {
          var o = Math.max(0, Math.min(1, e * 7 - q)).toFixed(2);
          faces[q].setAttribute("opacity", o);
          nums[q].setAttribute("opacity", o);
        }
      });
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
